+                    Long.MAX_VALUE, brokerConfig.getPopReviveMaxReturnSizePerRead());
+                if (consumerRecords == null || consumerRecords.isEmpty()) {
+                    break;
+                }
+                for (PopConsumerRecord record : consumerRecords) {
+                    PopCheckPoint ck = new PopCheckPoint();
