+    }
+
+    @Override
+    public void shutdown() {
+        // Block shutdown thread until write records finish
+        super.shutdown();
+        do {
+            this.waitForRunning(10);
+        }
+        while (consumerRunning.get());
+        if (this.popConsumerCache != null) {
+            this.popConsumerCache.shutdown();
